/// A data-access failure.
#[derive(Debug)]
pub enum StoreError {
    /// A query or a body names a field the object does not have.
    UnknownField {
        object: &'static str,
        field: String,
    },
    /// A value does not fit its column, or a filter does not fit its field.
    BadValue {
        field: String,
        message: String,
    },
    /// A stored value the model does not describe.
    Decode {
        field: String,
        message: String,
    },
    Unsupported(String),
    Database(sqlx::Error),
}

impl fmt::Display for StoreError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            StoreError::UnknownField { object, field } => {
                write!(f, "{object} has no field `{field}`")
            }
            StoreError::BadValue { field, message } => write!(f, "`{field}`: {message}"),
            StoreError::Decode { field, message } => write!(f, "reading `{field}`: {message}"),
            StoreError::Unsupported(m) => f.write_str(m),
            StoreError::Database(e) => write!(f, "{e}"),
        }
    }
}

impl std::error::Error for StoreError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            StoreError::Database(e) => Some(e),
            _ => None,
        }
    }
}

impl From<sqlx::Error> for StoreError {
    fn from(e: sqlx::Error) -> Self {
        StoreError::Database(e)
    }
}

fn bad(field: &str, message: impl Into<String>) -> StoreError {
    StoreError::BadValue { field: field.to_string(), message: message.into() }
}

fn decode_err(field: &str, message: impl fmt::Display) -> StoreError {
    StoreError::Decode { field: field.to_string(), message: message.to_string() }
}

