/// A filter operator.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Op {
    Eq,
    Ne,
    Gt,
    Gte,
    Lt,
    Lte,
    In,
    Like,
    IsNull,
}

impl Op {
    /// The operator of its wire name.
    pub fn of(name: &str) -> Option<Op> {
        Some(match name {
            "eq" => Op::Eq,
            "ne" => Op::Ne,
            "gt" => Op::Gt,
            "gte" => Op::Gte,
            "lt" => Op::Lt,
            "lte" => Op::Lte,
            "in" => Op::In,
            "like" => Op::Like,
            "isNull" => Op::IsNull,
            _ => return None,
        })
    }

    fn sql(self) -> &'static str {
        match self {
            Op::Eq => "=",
            Op::Ne => "<>",
            Op::Gt => ">",
            Op::Gte => ">=",
            Op::Lt => "<",
            Op::Lte => "<=",
            Op::Like => "LIKE",
            Op::In | Op::IsNull => "",
        }
    }
}

/// A condition on a model's fields. Several conditions compose with AND.
#[derive(Debug, Clone, PartialEq)]
pub enum Filter {
    Field { field: String, op: Op, value: Value },
    And(Vec<Filter>),
}

impl Filter {
    pub fn field(field: impl Into<String>, op: Op, value: impl Into<Value>) -> Filter {
        Filter::Field { field: field.into(), op, value: value.into() }
    }

    /// The filter of its JSON form: `{ "<field>": { "<op>": value }, "and": [ ... ] }`, each
    /// key one more condition ANDed with the rest.
    pub fn from_json(value: &Value) -> Result<Filter, StoreError> {
        let Value::Object(map) = value else {
            return Err(bad("filter", "a filter is an object"));
        };
        let mut all = Vec::new();
        for (key, v) in map {
            if key == "and" {
                let Value::Array(items) = v else {
                    return Err(bad("and", "`and` is a list of filters"));
                };
                for item in items {
                    all.push(Filter::from_json(item)?);
                }
                continue;
            }
            let Value::Object(ops) = v else {
                return Err(bad(key, "a field's condition is an object of operators"));
            };
            for (op, operand) in ops {
                let op = Op::of(op).ok_or_else(|| bad(key, format!("unknown operator `{op}`")))?;
                all.push(Filter::field(key.clone(), op, operand.clone()));
            }
        }
        Ok(if all.len() == 1 { all.remove(0) } else { Filter::And(all) })
    }
}

