/// The engine a connection talks to.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Engine {
    Postgres,
    Sqlite,
}

/// A value bound to a placeholder.
#[derive(Debug, Clone, PartialEq)]
pub enum Bind {
    Null,
    Bool(bool),
    Int(i64),
    Real(f64),
    Text(String),
    Ints(Vec<i64>),
    Texts(Vec<String>),
}

/// A database connection a store runs on: a Postgres or a SQLite connection, or a
/// transaction on one (`&mut *tx`).
pub trait Conn: Send {
    fn engine(&self) -> Engine;

    /// Runs `sql` and reads every row, each column decoded as `columns` says, in order.
    fn rows<'a>(
        &'a mut self,
        sql: &'a str,
        binds: Vec<Bind>,
        columns: &'a [Column],
    ) -> impl Future<Output = Result<Vec<Map<String, Value>>, StoreError>> + Send + 'a;

    /// Runs `sql` and reads the one integer its one row holds.
    fn scalar<'a>(
        &'a mut self,
        sql: &'a str,
        binds: Vec<Bind>,
    ) -> impl Future<Output = Result<i64, StoreError>> + Send + 'a;

    /// Runs `sql` and answers the number of rows it changed.
    fn execute<'a>(
        &'a mut self,
        sql: &'a str,
        binds: Vec<Bind>,
    ) -> impl Future<Output = Result<u64, StoreError>> + Send + 'a;
}

/// A statement as it is built: its text and its binds, numbered for the engine.
struct Sql {
    engine: Engine,
    text: String,
    binds: Vec<Bind>,
}

impl Sql {
    fn new(engine: Engine) -> Self {
        Sql { engine, text: String::new(), binds: Vec::new() }
    }

    fn push(&mut self, s: &str) {
        self.text.push_str(s);
    }

    /// A placeholder for `bind`, cast to the column's type on Postgres.
    fn param(&mut self, bind: Bind, column: &Column) {
        self.binds.push(bind);
        match self.engine {
            Engine::Postgres => {
                let n = self.binds.len();
                let ty = pg_type(column);
                self.text.push_str(&format!("CAST(${n} AS {ty})"));
            }
            Engine::Sqlite => self.text.push('?'),
        }
    }
}

fn quote(name: &str) -> String {
    format!("\"{}\"", name.replace('"', "\"\""))
}

fn table_ref(table: &Table) -> String {
    match table.schema {
        Some(s) => format!("{}.{}", quote(s), quote(table.name)),
        None => quote(table.name),
    }
}

fn pg_type(c: &Column) -> String {
    if let Some(ty) = c.stored_as {
        return if c.array { format!("{ty}[]") } else { ty.to_string() };
    }
    logical_pg_type(c)
}

/// The Postgres type the model's `kind` reads as.
fn logical_pg_type(c: &Column) -> String {
    let base = match c.kind {
        Kind::Text | Kind::StringEnum(_) => "text",
        Kind::Int | Kind::IntEnum(_) => "integer",
        Kind::Long => "bigint",
        Kind::Double => "double precision",
        Kind::Float => "real",
        Kind::Bool => "boolean",
        Kind::Decimal => "numeric",
        Kind::Date => "date",
        Kind::Time => "time",
        Kind::Timestamp => "timestamp",
        Kind::TimestampTz => "timestamptz",
        Kind::Uuid => "uuid",
        Kind::Inet => "inet",
        Kind::Duration => "interval",
        Kind::Json => return "jsonb".to_string(),
    };
    if c.array {
        format!("{base}[]")
    } else {
        base.to_string()
    }
}

/// What a SELECT reads for a column: on Postgres an exact decimal and a uuid as text, an
/// address without its netmask, and a column of its own SQL type as the type of its kind. A
/// view's number is read as the type of its kind too, because the view's SQL decides its
/// column's type (`AVG` of an integer is `NUMERIC` on Postgres).
fn read_expr(engine: Engine, table: &Table, c: &Column) -> String {
    let col = quote(c.column);
    let view_number = !table.writable
        && !c.array
        && matches!(c.kind, Kind::Int | Kind::Long | Kind::Double | Kind::Float);
    if engine == Engine::Postgres && (c.stored_as.is_some() || view_number) {
        return format!("CAST({col} AS {})", logical_pg_type(c));
    }
    match (engine, c.kind, c.array) {
        (Engine::Postgres, Kind::Decimal | Kind::Uuid, false) => format!("{col}::text"),
        (Engine::Postgres, Kind::Decimal | Kind::Uuid, true) => format!("{col}::text[]"),
        (Engine::Postgres, Kind::Inet, false) => format!("host({col})"),
        _ => col,
    }
}

fn select_list(engine: Engine, table: &Table) -> String {
    table.columns.iter().map(|c| read_expr(engine, table, c)).collect::<Vec<_>>().join(", ")
}

// ---- binding a JSON value ----------------------------------------------------------------

fn text_of<'v>(field: &str, v: &'v Value, what: &str) -> Result<&'v str, StoreError> {
    v.as_str().ok_or_else(|| bad(field, format!("{what} is a string")))
}

fn int_of(field: &str, v: &Value) -> Result<i64, StoreError> {
    if let Some(i) = v.as_i64() {
        return Ok(i);
    }
    // A 64-bit value may arrive as its base-10 text, so it survives a JSON number.
    if let Some(i) = v.as_str().and_then(|s| s.parse::<i64>().ok()) {
        return Ok(i);
    }
    Err(bad(field, "an integer is a number or its base-10 text"))
}

/// The bind of one value of a column of `kind`.
fn scalar_bind(engine: Engine, field: &str, kind: Kind, v: &Value) -> Result<Bind, StoreError> {
    if v.is_null() {
        return Ok(Bind::Null);
    }
    Ok(match kind {
        Kind::Text | Kind::Date | Kind::Time | Kind::Timestamp | Kind::TimestampTz | Kind::Inet => {
            Bind::Text(text_of(field, v, "the value")?.to_string())
        }
        // A UUID's canonical text is lower case, which is what Postgres reads back too.
        Kind::Uuid => Bind::Text(text_of(field, v, "a UUID")?.to_ascii_lowercase()),
        Kind::Int | Kind::Long => Bind::Int(int_of(field, v)?),
        Kind::Double | Kind::Float => {
            Bind::Real(v.as_f64().ok_or_else(|| bad(field, "a number is a JSON number"))?)
        }
        Kind::Bool => {
            let b = v.as_bool().ok_or_else(|| bad(field, "a boolean is true or false"))?;
            match engine {
                Engine::Postgres => Bind::Bool(b),
                Engine::Sqlite => Bind::Int(i64::from(b)),
            }
        }
        Kind::Decimal => match v {
            Value::String(s) => {
                let d =
                    meta_support::wire::Decimal::parse(s).map_err(|e| bad(field, e.to_string()))?;
                Bind::Text(d.as_str().to_string())
            }
            Value::Number(n) => Bind::Text(n.to_string()),
            _ => return Err(bad(field, "a decimal is a string or a number")),
        },
        Kind::Duration => {
            let text = text_of(field, v, "a duration")?;
            let d =
                meta_support::wire::Duration::parse(text).map_err(|e| bad(field, e.to_string()))?;
            match engine {
                // In microseconds, the interval's own resolution: Postgres reads no sign on an
                // ISO duration.
                Engine::Postgres => Bind::Text(format!("{} microseconds", d.nanos() / 1000)),
                Engine::Sqlite => Bind::Int(
                    i64::try_from(d.nanos() / 1000)
                        .map_err(|_| bad(field, "the duration is too long"))?,
                ),
            }
        }
        Kind::Json => Bind::Text(v.to_string()),
        Kind::StringEnum(map) => {
            let symbol = text_of(field, v, "an enum member")?;
            let stored = map
                .iter()
                .find(|(m, _)| *m == symbol)
                .map(|(_, t)| *t)
                .ok_or_else(|| bad(field, format!("`{symbol}` is not a member")))?;
            Bind::Text(stored.to_string())
        }
        Kind::IntEnum(map) => {
            let symbol = text_of(field, v, "an enum member")?;
            let stored = map
                .iter()
                .find(|(m, _)| *m == symbol)
                .map(|(_, i)| *i)
                .ok_or_else(|| bad(field, format!("`{symbol}` is not a member")))?;
            Bind::Int(stored)
        }
    })
}

/// The bind of a column's value: an array is bound whole.
fn bind_of(engine: Engine, c: &Column, v: &Value) -> Result<Bind, StoreError> {
    if !c.array || v.is_null() {
        return scalar_bind(engine, c.field, c.kind, v);
    }
    let Value::Array(items) = v else {
        return Err(bad(c.field, "the value is a list"));
    };
    let binds = items
        .iter()
        .map(|item| scalar_bind(engine, c.field, c.kind, item))
        .collect::<Result<Vec<_>, _>>()?;
    match engine {
        Engine::Sqlite => {
            let stored: Vec<Value> = binds
                .into_iter()
                .map(|b| match b {
                    Bind::Null => Value::Null,
                    Bind::Bool(b) => Value::Bool(b),
                    Bind::Int(i) => Value::from(i),
                    Bind::Real(r) => Value::from(r),
                    Bind::Text(t) => Value::String(t),
                    Bind::Ints(_) | Bind::Texts(_) => Value::Null,
                })
                .collect();
            Ok(Bind::Text(Value::Array(stored).to_string()))
        }
        Engine::Postgres => {
            if binds.iter().all(|b| matches!(b, Bind::Int(_))) {
                Ok(Bind::Ints(
                    binds.into_iter().map(|b| if let Bind::Int(i) = b { i } else { 0 }).collect(),
                ))
            } else if binds.iter().all(|b| matches!(b, Bind::Text(_))) {
                Ok(Bind::Texts(
                    binds
                        .into_iter()
                        .map(|b| if let Bind::Text(t) = b { t } else { String::new() })
                        .collect(),
                ))
            } else {
                Err(StoreError::Unsupported(format!("`{}`: an array of this type", c.field)))
            }
        }
    }
}

// ---- decoding a stored value ---------------------------------------------------------------

fn int_enum_member(field: &str, map: &[(&str, i64)], stored: i64) -> Result<Value, StoreError> {
    map.iter()
        .find(|(_, i)| *i == stored)
        .map(|(m, _)| Value::String((*m).to_string()))
        .ok_or_else(|| decode_err(field, format!("the stored value {stored} is no member")))
}

fn string_enum_member(
    field: &str,
    map: &[(&str, &str)],
    stored: &str,
) -> Result<Value, StoreError> {
    map.iter()
        .find(|(_, t)| *t == stored)
        .map(|(m, _)| Value::String((*m).to_string()))
        .ok_or_else(|| decode_err(field, format!("the stored value `{stored}` is no member")))
}

fn decimal_text(field: &str, text: &str) -> Result<Value, StoreError> {
    meta_support::wire::Decimal::parse(text)
        .map(|d| Value::String(d.as_str().to_string()))
        .map_err(|e| decode_err(field, e))
}

fn decimal_real(field: &str, r: f64) -> Result<Value, StoreError> {
    meta_support::wire::Decimal::from_f64(r)
        .map(|d| Value::String(d.as_str().to_string()))
        .ok_or_else(|| decode_err(field, "a decimal must be finite"))
}

fn duration_nanos(nanos: i128) -> Value {
    Value::String(meta_support::wire::Duration::from_nanos(nanos).to_string())
}

fn number(field: &str, r: f64) -> Result<Value, StoreError> {
    serde_json::Number::from_f64(r)
        .map(Value::Number)
        .ok_or_else(|| decode_err(field, "a number must be finite"))
}

#[cfg(feature = "postgres")]
mod pg {
    use super::*;
    use chrono::Timelike;
    use sqlx::postgres::types::PgInterval;
    use sqlx::postgres::{PgArguments, PgRow};
    use sqlx::{Arguments, Row};

    fn args(binds: Vec<Bind>) -> Result<PgArguments, StoreError> {
        let mut a = PgArguments::default();
        for b in binds {
            let r = match b {
                Bind::Null => a.add(Option::<String>::None),
                Bind::Bool(v) => a.add(v),
                Bind::Int(v) => a.add(v),
                Bind::Real(v) => a.add(v),
                Bind::Text(v) => a.add(v),
                Bind::Ints(v) => a.add(v),
                Bind::Texts(v) => a.add(v),
            };
            r.map_err(|e| StoreError::Database(sqlx::Error::Encode(e)))?;
        }
        Ok(a)
    }

    /// The fractional seconds of a time: `.` and the digits without trailing zeros, or nothing
    /// for a whole second.
    /// The fraction of a second on the wire: milliseconds, truncated, with no trailing zeros
    /// and no dot when there are none (normalization.md).
    fn fraction(nanos: u32) -> String {
        let millis = nanos / 1_000_000;
        if millis == 0 {
            return String::new();
        }
        let digits = format!("{millis:03}");
        format!(".{}", digits.trim_end_matches('0'))
    }

    fn get<'r, T: sqlx::Decode<'r, sqlx::Postgres> + sqlx::Type<sqlx::Postgres>>(
        row: &'r PgRow,
        i: usize,
        field: &str,
    ) -> Result<Option<T>, StoreError> {
        row.try_get::<Option<T>, _>(i).map_err(|e| decode_err(field, e))
    }

    fn scalar(row: &PgRow, i: usize, c: &Column) -> Result<Value, StoreError> {
        let f = c.field;
        let v = match c.kind {
            Kind::Text | Kind::Decimal | Kind::Uuid | Kind::Inet | Kind::StringEnum(_) => {
                match (get::<String>(row, i, f)?, c.kind) {
                    (None, _) => Value::Null,
                    (Some(s), Kind::Decimal) => decimal_text(f, &s)?,
                    (Some(s), Kind::StringEnum(map)) => string_enum_member(f, map, &s)?,
                    (Some(s), _) => Value::String(s),
                }
            }
            Kind::Int => get::<i32>(row, i, f)?.map_or(Value::Null, Value::from),
            Kind::IntEnum(map) => match get::<i32>(row, i, f)? {
                None => Value::Null,
                Some(s) => int_enum_member(f, map, i64::from(s))?,
            },
            Kind::Long => get::<i64>(row, i, f)?.map_or(Value::Null, Value::from),
            Kind::Double => match get::<f64>(row, i, f)? {
                None => Value::Null,
                Some(r) => number(f, r)?,
            },
            Kind::Float => match get::<f32>(row, i, f)? {
                None => Value::Null,
                // The shortest text of the f32, so 0.1 reads back as 0.1 and not its f64 widening.
                Some(r) => number(f, r.to_string().parse::<f64>().unwrap_or(f64::from(r)))?,
            },
            Kind::Bool => get::<bool>(row, i, f)?.map_or(Value::Null, Value::Bool),
            Kind::Date => get::<chrono::NaiveDate>(row, i, f)?
                .map_or(Value::Null, |d| Value::String(d.format("%Y-%m-%d").to_string())),
            Kind::Time => get::<chrono::NaiveTime>(row, i, f)?.map_or(Value::Null, |t| {
                Value::String(format!("{}{}", t.format("%H:%M:%S"), fraction(t.nanosecond())))
            }),
            Kind::Timestamp => get::<chrono::NaiveDateTime>(row, i, f)?.map_or(Value::Null, |t| {
                Value::String(format!(
                    "{}{}",
                    t.format("%Y-%m-%dT%H:%M:%S"),
                    fraction(t.nanosecond())
                ))
            }),
            Kind::TimestampTz => {
                get::<chrono::DateTime<chrono::Utc>>(row, i, f)?.map_or(Value::Null, |t| {
                    Value::String(format!(
                        "{}{}Z",
                        t.format("%Y-%m-%dT%H:%M:%S"),
                        fraction(t.nanosecond())
                    ))
                })
            }
            Kind::Duration => match get::<PgInterval>(row, i, f)? {
                None => Value::Null,
                Some(iv) if iv.months != 0 => {
                    return Err(decode_err(f, "an interval with months has no fixed length"));
                }
                Some(iv) => duration_nanos(
                    i128::from(iv.days) * 86_400_000_000_000 + i128::from(iv.microseconds) * 1000,
                ),
            },
            Kind::Json => get::<Value>(row, i, f)?.unwrap_or(Value::Null),
        };
        Ok(v)
    }

    fn array(row: &PgRow, i: usize, c: &Column) -> Result<Value, StoreError> {
        let f = c.field;
        let items: Option<Vec<Value>> = match c.kind {
            Kind::Int => {
                get::<Vec<i32>>(row, i, f)?.map(|v| v.into_iter().map(Value::from).collect())
            }
            Kind::IntEnum(map) => match get::<Vec<i32>>(row, i, f)? {
                None => None,
                Some(v) => Some(
                    v.into_iter()
                        .map(|s| int_enum_member(f, map, i64::from(s)))
                        .collect::<Result<_, _>>()?,
                ),
            },
            Kind::Long => {
                get::<Vec<i64>>(row, i, f)?.map(|v| v.into_iter().map(Value::from).collect())
            }
            Kind::Text | Kind::Uuid => {
                get::<Vec<String>>(row, i, f)?.map(|v| v.into_iter().map(Value::String).collect())
            }
            Kind::Decimal => match get::<Vec<String>>(row, i, f)? {
                None => None,
                Some(v) => Some(v.iter().map(|s| decimal_text(f, s)).collect::<Result<_, _>>()?),
            },
            Kind::StringEnum(map) => match get::<Vec<String>>(row, i, f)? {
                None => None,
                Some(v) => Some(
                    v.iter().map(|s| string_enum_member(f, map, s)).collect::<Result<_, _>>()?,
                ),
            },
            Kind::Bool => {
                get::<Vec<bool>>(row, i, f)?.map(|v| v.into_iter().map(Value::Bool).collect())
            }
            _ => return Err(StoreError::Unsupported(format!("`{f}`: an array of this type"))),
        };
        Ok(items.map_or(Value::Null, Value::Array))
    }

    fn decode(row: &PgRow, columns: &[Column]) -> Result<Map<String, Value>, StoreError> {
        let mut out = Map::new();
        for (i, c) in columns.iter().enumerate() {
            let v = if c.array { array(row, i, c)? } else { scalar(row, i, c)? };
            out.insert(c.field.to_string(), v);
        }
        Ok(out)
    }

    impl Conn for sqlx::PgConnection {
        fn engine(&self) -> Engine {
            Engine::Postgres
        }

        async fn rows<'a>(
            &'a mut self,
            sql: &'a str,
            binds: Vec<Bind>,
            columns: &'a [Column],
        ) -> Result<Vec<Map<String, Value>>, StoreError> {
            let rows = sqlx::query_with(sql, args(binds)?).fetch_all(&mut *self).await?;
            rows.iter().map(|r| decode(r, columns)).collect()
        }

        async fn scalar<'a>(
            &'a mut self,
            sql: &'a str,
            binds: Vec<Bind>,
        ) -> Result<i64, StoreError> {
            let row = sqlx::query_with(sql, args(binds)?).fetch_one(&mut *self).await?;
            Ok(row.try_get::<i64, _>(0)?)
        }

        async fn execute<'a>(
            &'a mut self,
            sql: &'a str,
            binds: Vec<Bind>,
        ) -> Result<u64, StoreError> {
            let done = sqlx::query_with(sql, args(binds)?).execute(&mut *self).await?;
            Ok(done.rows_affected())
        }
    }
}

#[cfg(feature = "sqlite")]
mod sqlite {
    use super::*;
    use sqlx::sqlite::{SqliteArguments, SqliteRow};
    use sqlx::{Arguments, Row, TypeInfo, ValueRef};

    fn args(binds: Vec<Bind>) -> Result<SqliteArguments<'static>, StoreError> {
        let mut a = SqliteArguments::default();
        for b in binds {
            let r = match b {
                Bind::Null => a.add(Option::<String>::None),
                Bind::Bool(v) => a.add(i64::from(v)),
                Bind::Int(v) => a.add(v),
                Bind::Real(v) => a.add(v),
                Bind::Text(v) => a.add(v),
                Bind::Ints(v) => a.add(Value::from(v).to_string()),
                Bind::Texts(v) => a.add(Value::from(v).to_string()),
            };
            r.map_err(|e| StoreError::Database(sqlx::Error::Encode(e)))?;
        }
        Ok(a)
    }

    /// One stored value, by the storage class SQLite gave it.
    enum Stored {
        Null,
        Int(i64),
        Real(f64),
        Text(String),
    }

    fn stored(row: &SqliteRow, i: usize, field: &str) -> Result<Stored, StoreError> {
        let raw = row.try_get_raw(i).map_err(|e| decode_err(field, e))?;
        if raw.is_null() {
            return Ok(Stored::Null);
        }
        let class = raw.type_info().name().to_string();
        Ok(match class.as_str() {
            "INTEGER" | "BOOLEAN" => {
                Stored::Int(row.try_get::<i64, _>(i).map_err(|e| decode_err(field, e))?)
            }
            "REAL" => Stored::Real(row.try_get::<f64, _>(i).map_err(|e| decode_err(field, e))?),
            _ => Stored::Text(row.try_get::<String, _>(i).map_err(|e| decode_err(field, e))?),
        })
    }

    fn from_stored(field: &str, kind: Kind, s: Stored) -> Result<Value, StoreError> {
        Ok(match (kind, s) {
            (_, Stored::Null) => Value::Null,
            (Kind::Bool, Stored::Int(i)) => Value::Bool(i != 0),
            (Kind::IntEnum(map), Stored::Int(i)) => int_enum_member(field, map, i)?,
            (Kind::StringEnum(map), Stored::Text(t)) => string_enum_member(field, map, &t)?,
            (Kind::Decimal, Stored::Int(i)) => Value::String(i.to_string()),
            (Kind::Decimal, Stored::Real(r)) => decimal_real(field, r)?,
            (Kind::Decimal, Stored::Text(t)) => decimal_text(field, &t)?,
            (Kind::Duration, Stored::Int(micros)) => duration_nanos(i128::from(micros) * 1000),
            (Kind::Json, Stored::Text(t)) => {
                serde_json::from_str(&t).map_err(|e| decode_err(field, e))?
            }
            (Kind::Int | Kind::Long, Stored::Int(i)) => Value::from(i),
            (Kind::Double | Kind::Float, Stored::Int(i)) => Value::from(i as f64),
            (Kind::Double | Kind::Float, Stored::Real(r)) => number(field, r)?,
            (_, Stored::Text(t)) => Value::String(t),
            (_, Stored::Int(i)) => Value::from(i),
            (_, Stored::Real(r)) => number(field, r)?,
        })
    }

    /// An element of an array column, which is JSON text.
    fn element(field: &str, kind: Kind, v: Value) -> Result<Value, StoreError> {
        let s = match v {
            Value::Null => Stored::Null,
            Value::Bool(b) => Stored::Int(i64::from(b)),
            Value::Number(n) => match n.as_i64() {
                Some(i) => Stored::Int(i),
                None => Stored::Real(n.as_f64().unwrap_or(f64::NAN)),
            },
            Value::String(t) => Stored::Text(t),
            other => return Ok(other),
        };
        from_stored(field, kind, s)
    }

    fn decode(row: &SqliteRow, columns: &[Column]) -> Result<Map<String, Value>, StoreError> {
        let mut out = Map::new();
        for (i, c) in columns.iter().enumerate() {
            let s = stored(row, i, c.field)?;
            let v = if c.array {
                match s {
                    Stored::Null => Value::Null,
                    Stored::Text(t) => match serde_json::from_str::<Value>(&t)
                        .map_err(|e| decode_err(c.field, e))?
                    {
                        Value::Array(items) => Value::Array(
                            items
                                .into_iter()
                                .map(|v| element(c.field, c.kind, v))
                                .collect::<Result<_, _>>()?,
                        ),
                        _ => return Err(decode_err(c.field, "an array column holds a JSON list")),
                    },
                    _ => return Err(decode_err(c.field, "an array column holds JSON text")),
                }
            } else {
                from_stored(c.field, c.kind, s)?
            };
            out.insert(c.field.to_string(), v);
        }
        Ok(out)
    }

    impl Conn for sqlx::SqliteConnection {
        fn engine(&self) -> Engine {
            Engine::Sqlite
        }

        async fn rows<'a>(
            &'a mut self,
            sql: &'a str,
            binds: Vec<Bind>,
            columns: &'a [Column],
        ) -> Result<Vec<Map<String, Value>>, StoreError> {
            let rows = sqlx::query_with(sql, args(binds)?).fetch_all(&mut *self).await?;
            rows.iter().map(|r| decode(r, columns)).collect()
        }

        async fn scalar<'a>(
            &'a mut self,
            sql: &'a str,
            binds: Vec<Bind>,
        ) -> Result<i64, StoreError> {
            let row = sqlx::query_with(sql, args(binds)?).fetch_one(&mut *self).await?;
            Ok(row.try_get::<i64, _>(0)?)
        }

        async fn execute<'a>(
            &'a mut self,
            sql: &'a str,
            binds: Vec<Bind>,
        ) -> Result<u64, StoreError> {
            let done = sqlx::query_with(sql, args(binds)?).execute(&mut *self).await?;
            Ok(done.rows_affected())
        }
    }
}

// ---- statements ----------------------------------------------------------------------------

fn where_filter(sql: &mut Sql, table: &Table, f: &Filter) -> Result<(), StoreError> {
    match f {
        Filter::And(all) if all.is_empty() => sql.push("1 = 1"),
        Filter::And(all) => {
            sql.push("(");
            for (i, f) in all.iter().enumerate() {
                if i > 0 {
                    sql.push(" AND ");
                }
                where_filter(sql, table, f)?;
            }
            sql.push(")");
        }
        Filter::Field { field, op, value } => {
            let c = *table.column(field)?;
            if (c.array || c.kind == Kind::Json) && *op != Op::IsNull {
                return Err(bad(field, "a list or a JSON value takes only `isNull`"));
            }
            let col = quote(c.column);
            match op {
                Op::IsNull => {
                    let yes = value
                        .as_bool()
                        .ok_or_else(|| bad(field, "`isNull` takes true or false"))?;
                    sql.push(&format!("{col} IS {}NULL", if yes { "" } else { "NOT " }));
                }
                Op::Eq | Op::Ne if value.is_null() => {
                    sql.push(&format!("{col} IS {}NULL", if *op == Op::Ne { "NOT " } else { "" }));
                }
                Op::In => {
                    let Value::Array(items) = value else {
                        return Err(bad(field, "`in` takes a list"));
                    };
                    if items.is_empty() {
                        sql.push("1 = 0");
                        return Ok(());
                    }
                    sql.push(&format!("{col} IN ("));
                    for (i, item) in items.iter().enumerate() {
                        if i > 0 {
                            sql.push(", ");
                        }
                        let b = scalar_bind(sql.engine, field, c.kind, item)?;
                        sql.param(b, &c);
                    }
                    sql.push(")");
                }
                Op::Like => {
                    if c.kind != Kind::Text {
                        return Err(bad(field, "`like` applies to text"));
                    }
                    let b = scalar_bind(sql.engine, field, c.kind, value)?;
                    sql.push(&format!("{col} LIKE "));
                    sql.param(b, &c);
                }
                _ => {
                    let b = scalar_bind(sql.engine, field, c.kind, value)?;
                    sql.push(&format!("{col} {} ", op.sql()));
                    sql.param(b, &c);
                }
            }
        }
    }
    Ok(())
}

/// ` AND "<discriminator>" = <value>` (or ` WHERE ...` when `first`), for a subtype.
fn scope(sql: &mut Sql, table: &Table, first: bool) -> Result<(), StoreError> {
    if let Some((field, value)) = table.discriminator {
        let c = *table.column(field)?;
        sql.push(&format!(" {} {} = ", if first { "WHERE" } else { "AND" }, quote(c.column)));
        sql.param(Bind::Text(value.to_string()), &c);
    }
    Ok(())
}

fn select(engine: Engine, table: &Table) -> Sql {
    let mut sql = Sql::new(engine);
    sql.push(&format!("SELECT {} FROM {}", select_list(engine, table), table_ref(table)));
    sql
}

fn key_where(sql: &mut Sql, table: &Table, key: &Value) -> Result<(), StoreError> {
    let c = *table.key_column()?;
    let b = scalar_bind(sql.engine, c.field, c.kind, key)?;
    sql.push(&format!(" WHERE {} = ", quote(c.column)));
    sql.param(b, &c);
    scope(sql, table, false)
}

fn rows_into<T: DeserializeOwned>(
    table: &Table,
    rows: Vec<Map<String, Value>>,
) -> Result<Vec<T>, StoreError> {
    rows.into_iter()
        .map(|r| serde_json::from_value(Value::Object(r)).map_err(|e| decode_err(table.object, e)))
        .collect()
}

fn body_of<B: Serialize>(table: &Table, body: &B) -> Result<Map<String, Value>, StoreError> {
    match serde_json::to_value(body) {
        Ok(Value::Object(m)) => Ok(m),
        Ok(_) => Err(bad(table.object, "a body is an object")),
        Err(e) => Err(bad(table.object, e.to_string())),
    }
}

/// The row with key `key`, or `None`.
pub async fn get<T: DeserializeOwned, C: Conn + ?Sized>(
    c: &mut C,
    table: &Table,
    key: impl Serialize,
) -> Result<Option<T>, StoreError> {
    let key = serde_json::to_value(key).map_err(|e| bad(table.object, e.to_string()))?;
    let mut sql = select(c.engine(), table);
    key_where(&mut sql, table, &key)?;
    let rows = c.rows(&sql.text, sql.binds, table.columns).await?;
    Ok(rows_into(table, rows)?.into_iter().next())
}

/// The rows a query selects, in its order and page.
pub async fn list<T: DeserializeOwned, C: Conn + ?Sized>(
    c: &mut C,
    table: &Table,
    query: &Query,
) -> Result<Vec<T>, StoreError> {
    let mut sql = select(c.engine(), table);
    scope(&mut sql, table, true)?;
    if let Some(f) = &query.filter {
        sql.push(if table.discriminator.is_some() { " AND " } else { " WHERE " });
        where_filter(&mut sql, table, f)?;
    }
    if !query.sort.is_empty() {
        let mut order = Vec::new();
        for s in &query.sort {
            let col = table.column(&s.field)?;
            // A null sorts as larger than any value.
            order.push(if s.descending {
                format!("{} DESC NULLS FIRST", quote(col.column))
            } else {
                format!("{} ASC NULLS LAST", quote(col.column))
            });
        }
        sql.push(&format!(" ORDER BY {}", order.join(", ")));
    }
    match (query.limit, query.offset) {
        (Some(l), Some(o)) => sql.push(&format!(" LIMIT {l} OFFSET {o}")),
        (Some(l), None) => sql.push(&format!(" LIMIT {l}")),
        (None, Some(o)) => sql.push(&match sql.engine {
            Engine::Postgres => format!(" OFFSET {o}"),
            Engine::Sqlite => format!(" LIMIT -1 OFFSET {o}"),
        }),
        (None, None) => {}
    }
    let rows = c.rows(&sql.text, sql.binds, table.columns).await?;
    rows_into(table, rows)
}

/// The number of rows a filter selects.
pub async fn count<C: Conn + ?Sized>(
    c: &mut C,
    table: &Table,
    filter: Option<&Filter>,
) -> Result<u64, StoreError> {
    let mut sql = Sql::new(c.engine());
    sql.push(&format!("SELECT COUNT(*) FROM {}", table_ref(table)));
    scope(&mut sql, table, true)?;
    if let Some(f) = filter {
        sql.push(if table.discriminator.is_some() { " AND " } else { " WHERE " });
        where_filter(&mut sql, table, f)?;
    }
    let n = c.scalar(&sql.text, sql.binds).await?;
    Ok(u64::try_from(n).unwrap_or(0))
}

/// Inserts the members `body` carries and reads the row back.
pub async fn create<T: DeserializeOwned, B: Serialize, C: Conn + ?Sized>(
    c: &mut C,
    table: &Table,
    body: &B,
) -> Result<T, StoreError> {
    table.require_writable()?;
    let mut body = body_of(table, body)?;
    if let Some((field, value)) = table.discriminator {
        match body.get(field) {
            None | Some(Value::Null) => {
                body.insert(field.to_string(), Value::String(value.to_string()));
            }
            Some(Value::String(v)) if v == value => {}
            Some(_) => return Err(bad(field, format!("a {} is always `{value}`", table.object))),
        }
    }
    let engine = c.engine();
    let mut sql = Sql::new(engine);
    let mut names = Vec::new();
    let mut values = Sql::new(engine);
    for (field, v) in &body {
        let col = *table.column(field)?;
        names.push(quote(col.column));
        if !values.text.is_empty() {
            values.push(", ");
        }
        let b = bind_of(engine, &col, v)?;
        values.param(b, &col);
    }
    if names.is_empty() {
        sql.push(&format!("INSERT INTO {} DEFAULT VALUES", table_ref(table)));
    } else {
        // The values were numbered from 1, as they are the statement's only binds.
        sql.push(&format!(
            "INSERT INTO {} ({}) VALUES ({})",
            table_ref(table),
            names.join(", "),
            values.text
        ));
        sql.binds = values.binds;
    }
    sql.push(&format!(" RETURNING {}", select_list(engine, table)));
    let rows = c.rows(&sql.text, sql.binds, table.columns).await?;
    rows_into(table, rows)?.into_iter().next().ok_or_else(|| {
        StoreError::Unsupported(format!("{}: the insert returned no row", table.object))
    })
}

/// Sets the members `patch` carries on the row with key `key` and reads it back; `None` when
/// there is no such row.
pub async fn update<T: DeserializeOwned, B: Serialize, C: Conn + ?Sized>(
    c: &mut C,
    table: &Table,
    key: impl Serialize,
    patch: &B,
) -> Result<Option<T>, StoreError> {
    table.require_writable()?;
    let key = serde_json::to_value(key).map_err(|e| bad(table.object, e.to_string()))?;
    let body = body_of(table, patch)?;
    if let Some((field, value)) = table.discriminator {
        if body.get(field).is_some_and(|v| v.as_str() != Some(value)) {
            return Err(bad(field, "the discriminator never changes"));
        }
    }
    if body.is_empty() {
        return get(c, table, key).await;
    }
    let engine = c.engine();
    let mut sql = Sql::new(engine);
    sql.push(&format!("UPDATE {} SET ", table_ref(table)));
    for (i, (field, v)) in body.iter().enumerate() {
        let col = *table.column(field)?;
        if i > 0 {
            sql.push(", ");
        }
        sql.push(&format!("{} = ", quote(col.column)));
        let b = bind_of(engine, &col, v)?;
        sql.param(b, &col);
    }
    key_where(&mut sql, table, &key)?;
    sql.push(&format!(" RETURNING {}", select_list(engine, table)));
    let rows = c.rows(&sql.text, sql.binds, table.columns).await?;
    Ok(rows_into(table, rows)?.into_iter().next())
}

/// Deletes the row with key `key`; `false` when there was none.
pub async fn delete<C: Conn + ?Sized>(
    c: &mut C,
    table: &Table,
    key: impl Serialize,
) -> Result<bool, StoreError> {
    table.require_writable()?;
    let key = serde_json::to_value(key).map_err(|e| bad(table.object, e.to_string()))?;
    let mut sql = Sql::new(c.engine());
    sql.push(&format!("DELETE FROM {}", table_ref(table)));
    key_where(&mut sql, table, &key)?;
    Ok(c.execute(&sql.text, sql.binds).await? > 0)
}

/// The guarded update of a lifecycle (ADR-0066 §6 step 5): sets `state` to `to` on the row
/// with key `key` only while its state is one of `from`, in one statement. `false` when no
/// row matched: the row is gone, or another writer moved it first. The caller re-reads to
/// tell which.
pub async fn transition<S: Serialize, C: Conn + ?Sized>(
    c: &mut C,
    table: &Table,
    key: impl Serialize,
    state: &str,
    from: &[S],
    to: &S,
) -> Result<bool, StoreError> {
    table.require_writable()?;
    let key = serde_json::to_value(key).map_err(|e| bad(table.object, e.to_string()))?;
    let value = |s: &S| serde_json::to_value(s).map_err(|e| bad(state, e.to_string()));
    let col = *table.column(state)?;
    let engine = c.engine();
    let mut sql = Sql::new(engine);
    sql.push(&format!("UPDATE {} SET {} = ", table_ref(table), quote(col.column)));
    sql.param(scalar_bind(engine, state, col.kind, &value(to)?)?, &col);
    key_where(&mut sql, table, &key)?;
    if from.is_empty() {
        return Ok(false);
    }
    sql.push(&format!(" AND {} IN (", quote(col.column)));
    for (i, f) in from.iter().enumerate() {
        if i > 0 {
            sql.push(", ");
        }
        sql.param(scalar_bind(engine, state, col.kind, &value(f)?)?, &col);
    }
    sql.push(")");
    Ok(c.execute(&sql.text, sql.binds).await? == 1)
}
